/// <summary>
/// CB220_PlannerCodes
/// </summary>
class METReqItemTableBuyerGroupUpdUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField dlgVendAccount;
    DialogField dlgInventSiteId;
    DialogField dlgInventLocationId;

}

Method.Source:
/// <summary>
/// Method to manage the vendor account parameter in UI builder
/// </summary>
/// <param name = "_identifierContractName">Method name from contract class</param>
/// <param name = "_mandatory">set the vendor account parameter to mandatory or optional</param>
public void postBuildVendAccount(IdentifierName _identifierContractName, boolean _mandatory = false)
{
    dlgVendAccount = this.bindInfo().getDialogField(this.dataContractObject(), _identifierContractName);
    dlgVendAccount.fieldControl().mandatory(_mandatory);
}

    /// <summary>
    /// Method to manage the site parameter in UI builder
    /// </summary>
    /// <param name = "_identifierContractName">Method name from contract class</param>
    /// <param name = "_mandatory">set the vendor account parameter to mandatory or optional</param>
    public void postBuildInventSiteId(IdentifierName _identifierContractName, boolean _mandatory = false)
    {
        dlgInventSiteId = this.bindInfo().getDialogField(this.dataContractObject(), _identifierContractName);
        dlgInventSiteId.fieldControl().mandatory(_mandatory);

        //override the modified method
        dlgInventSiteId.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METReqItemTableBuyerGroupUpdUIBuilder, modifiedInventSiteId), this);
    }

    /// <summary>
    /// Method to manage the warehouse parameter in UI builder
    /// </summary>
    /// <param name = "_identifierContractName">Method name from contract class</param>
    /// <param name = "_mandatory">set the vendor account parameter to mandatory or optional</param>
    public void postBuildInventLocationId(IdentifierName _identifierContractName, 
                                                 boolean _mandatory = false)
    {
        dlgInventLocationId = this.bindInfo().getDialogField(this.dataContractObject(), _identifierContractName);
        dlgInventLocationId.fieldControl().mandatory(_mandatory);

        //override the lookup method
        dlgInventLocationId.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METReqItemTableBuyerGroupUpdUIBuilder, lookupInventLocationId), this);
        //override the modified method
        dlgInventLocationId.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METReqItemTableBuyerGroupUpdUIBuilder, modifiedInventLocationId), this);
        //override the validate method
        dlgInventLocationId.registerOverrideMethod(methodStr(FormStringControl, validate), methodStr(METReqItemTableBuyerGroupUpdUIBuilder, validateInventLocationId), this);
    }

    /// <summary>
    /// Warehouse lookup filtered by site
    /// </summary>
    /// <param name = "_formStringControl">Warehouse control</param>
    private void lookupInventLocationId(FormStringControl _formStringControl)
    {
        Query query = new Query();
        QueryBuildDataSource qbds;
        SysTableLookup sysTableLookup;

        sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), _formStringControl);
            
        qbds = query.addDataSource(tableNum(InventLocation));
        qbds.addRange(fieldNum(InventLocation, InventSiteId)).value(dlgInventSiteId.value());

        sysTableLookup.addLookupfield(fieldNum(InventLocation, InventLocationId), true);
        sysTableLookup.addLookupfield(fieldNum(InventLocation, Name));
        sysTableLookup.addLookupfield(fieldNum(InventLocation, InventSiteId));
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();

    }

/// <summary>
/// When site is modified, need to delete the value in warehouse field
/// </summary>
/// <param name = "_ctrl">Site control</param>
/// <returns>true if successfully modified; otherwise, false</returns>
private boolean modifiedInventSiteId(FormStringControl _ctrl)
{
    dlgInventLocationId.value('');
    return (_ctrl.modified());
}

    /// <summary>
    /// When warehouse field updated, set the site if empty
    /// </summary>
    /// <param name = "_ctrl">Warehouse control</param>
    /// <returns>true if successfully modified; otherwise, false</returns>
    private boolean modifiedInventLocationId(FormStringControl _ctrl)
    {
        InventLocationId    inventLocationId = dlgInventLocationId.value();
        InventSiteId        inventSiteId     = dlgInventSiteId.value();
        
        if (!inventSiteId)
        {
            dlgInventSiteId.value(InventLocation::find(inventLocationId).InventSiteId);
        }

        return (_ctrl.modified());
    }

    /// <summary>
    /// Validate the warehouse control value
    /// </summary>
    /// <param name = "_ctrl">Warehouse control</param>
    /// <returns>true if validation successful; otherwise, false</returns>
    private boolean validateInventLocationId(FormStringControl _ctrl)
    {
        boolean ret = true;
   
        InventLocationId    inventLocationId = dlgInventLocationId.value();
        InventSiteId        inventSiteId     = dlgInventSiteId.value();

        if (inventLocationId)
        {
            InventLocation inventLocation = InventLocation::find(inventLocationId);

            if (inventLocation)
            {
                // if selected site is different from the selected warehouse's site
                if (inventSiteId && inventSiteId != inventLocation.InventSiteId)
                {
                    ret = checkFailed(strFmt("@SYS104861", inventLocationId, inventSiteId));
                }
            }
            else
            {
                // Not able to retrieve warehouse based on warehouse id
                ret = checkFailed(strFmt("@SCM:TableFieldValidation", inventLocationId, fieldId2PName(tableNum(InventLocation), fieldNum(InventLocation, InventLocationId)),
                        tableId2PName(tableNum(InventLocation))));
    
            }
        }
        return ret;
    }
